        let r100: nat = a % 100;

        let c20:  nat = r100 / 20;
        let r20:  nat = r100 % 20;

        let c10:  nat = r20 / 10;
        let r10:  nat = r20 % 10;

        let c5:   nat = r10 / 5;
        let r5:   nat = r10 % 5;

        // all that remains is in 1-unit coins
